function clearParticles() {
  particles.traverse(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
  arrows.traverse(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
  particles.clear();
  arrows.clear();
  dynamicLabels.forEach(removeDynamicLabel);
  dynamicLabels = [];
  particleRecords = [];
