  });
  dynamicLabels.push(label);
  const dir = charge === 'plus' ? new THREE.Vector3(-1, 0, 0) : new THREE.Vector3(1, 0, 0);
  const arrow = new THREE.ArrowHelper(dir, new THREE.Vector3(pos[0] + (charge === 'plus' ? -0.03 : 0.03), pos[1], pos[2]), 0.36, 0x222222, 0.10, 0.055);
