  } else {
    const ionN = Math.round(4 * c);
    const plusN = Math.ceil(ionN / 2);
    const minusN = ionN - plusN;
    const neutralN = Math.round(4 * c);
    for (let i = 0; i < plusN; i++) makeIon(i, 'plus', basePositions[(i * 5 + 2) % basePositions.length]);
    for (let i = 0; i < minusN; i++) makeIon(i + plusN, 'minus', basePositions[(i * 5 + 8) % basePositions.length]);
