  dynamicLabels = [];
  particleRecords = [];
}

function makeSphere(r, pos) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(r, 24, 16), greenMat);
  mesh.position.set(pos[0], pos[1], pos[2]);
  particles.add(mesh);
  return mesh;
}

function makeNeutralCluster(idx, pos) {
  const group = new THREE.Group();
  group.position.set(pos[0], pos[1], pos[2]);
  const r = 0.105 + 0.012 * (idx % 3);
  const offsets = idx % 2 === 0
    ? [[-r * 0.62, 0, 0], [r * 0.62, 0.02, 0.02], [0.02, r * 0.58, -0.02]]
    : [[-r * 0.55, 0.01, 0], [r * 0.55, 0, 0.02]];
  offsets.forEach(o => {
    const s = new THREE.Mesh(new THREE.SphereGeometry(r, 24, 16), greenMat);
    s.position.set(o[0], o[1], o[2]);
    group.add(s);
  });
  particles.add(group);
  particleRecords.push({
    kind: 'neutral',
    object: group,
    base: new THREE.Vector3(pos[0], pos[1], pos[2]),
    phase: idx * 0.91
  });
}

function makeIon(idx, charge, pos) {
  const mesh = makeSphere(0.13, pos);
  const label = addLabel(charge === 'plus' ? '+' : '&minus;', mesh.position.clone(), {
    fontSize: '16px',
    bold: true,
    color: '#ffffff'
  });
  dynamicLabels.push(label);
  const dir = charge === 'plus' ? new THREE.Vector3(-1, 0, 0) : new THREE.Vector3(1, 0, 0);
  const arrow = new THREE.ArrowHelper(dir, new THREE.Vector3(pos[0] + (charge === 'plus' ? -0.03 : 0.03), pos[1], pos[2]), 0.36, 0x222222, 0.10, 0.055);
  arrows.add(arrow);
  particleRecords.push({
    kind: charge,
    object: mesh,
    label,
    arrow,
    base: new THREE.Vector3(pos[0], pos[1], pos[2]),
    phase: idx * 0.73,
    speed: charge === 'plus' ? -0.18 : 0.18
  });
}

function brightnessFor(solution, c) {
  if (solution === 'KCl') return Math.min(Math.max(c / 1.2, 0), 1);
  if (solution === 'acetic acid solution') return Math.min(Math.max(0.25 * c / 1.2, 0), 0.35);
  return 0;
}

function setGlow(b) {
