function rebuildParticles() {
  clearParticles();
  const c = state.soluteConcentration;
  if (state.solutionType === 'ethanol') {
    const n = Math.round(6 * c);
    for (let i = 0; i < n; i++) makeNeutralCluster(i, basePositions[i % basePositions.length]);
  } else if (state.solutionType === 'KCl') {
    const n = Math.round(10 * c);
    const plusN = Math.ceil(n / 2);
    const minusN = n - plusN;
    for (let i = 0; i < plusN; i++) makeIon(i, 'plus', basePositions[(i * 2 + 1) % basePositions.length]);
    for (let i = 0; i < minusN; i++) makeIon(i + plusN, 'minus', basePositions[(i * 2 + 6) % basePositions.length]);
  } else {
    const ionN = Math.round(4 * c);
    const plusN = Math.ceil(ionN / 2);
    const minusN = ionN - plusN;
    const neutralN = Math.round(4 * c);
    for (let i = 0; i < plusN; i++) makeIon(i, 'plus', basePositions[(i * 5 + 2) % basePositions.length]);
    for (let i = 0; i < minusN; i++) makeIon(i + plusN, 'minus', basePositions[(i * 5 + 8) % basePositions.length]);
    for (let i = 0; i < neutralN; i++) makeNeutralCluster(i, basePositions[(i * 4 + 4) % basePositions.length]);
  }
}

