function updateParticleMotion() {
  const now = performance.now();
  const sec = (now - t0) / 1000;
  for (const rec of particleRecords) {
    if (rec.kind === 'neutral') {
      const amp = state.particleMotion ? 0.035 : 0;
      rec.object.position.set(
        rec.base.x + amp * Math.sin(sec * 1.3 + rec.phase),
        rec.base.y + amp * 0.65 * Math.cos(sec * 1.7 + rec.phase),
        rec.base.z + amp * 0.45 * Math.sin(sec * 1.1 + rec.phase * 1.7)
      );
    } else {
      let x = rec.base.x;
      if (state.particleMotion) {
        const span = 1.9;
        const left = -0.95;
        const raw = ((rec.base.x - left + rec.speed * sec) % span + span) % span;
        x = left + raw;
      }
      const y = rec.base.y + (state.particleMotion ? 0.025 * Math.sin(sec * 3 + rec.phase) : 0);
      const z = rec.base.z + (state.particleMotion ? 0.015 * Math.cos(sec * 2.2 + rec.phase) : 0);
      rec.object.position.set(x, y, z);
      rec.label.pos.copy(rec.object.position);
      const offset = rec.kind === 'plus' ? -0.08 : 0.08;
      rec.arrow.position.set(x + offset, y, z);
    }
  }
  requestAnimationFrame(updateParticleMotion);
}

