window.goToStep = function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  const startC = state.soluteConcentration;
  const endC = step.state.soluteConcentration;
  state.solutionType = step.state.solutionType;
  document.getElementById('stepText').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  showPopup(step.title, step.narration);
  const start = performance.now();
  const dur = 450;
  function tween() {
    const u = Math.min(1, (performance.now() - start) / dur);
    const eased = u * u * (3 - 2 * u);
    applyState({
      solutionType: step.state.solutionType,
      soluteConcentration: startC + (endC - startC) * eased
    });
    if (u < 1) requestAnimationFrame(tween);
  }
  tween();
};

