  panel.glowMat.opacity = amount <= 0 ? 0 : 0.16 + 0.42 * amount;
  const radius = amount <= 0 ? 0.001 : 0.34 + 0.30 * amount;
  panel.glow.scale.set(radius, radius, radius);
  panel.pointLight.intensity = 1.35 * amount;
  panel.filament.material.color.set(amount > 0 ? 0xff9500 : 0x777777);
}

function rebuildAllParticles() {
  const c = state.concentration;
  for (const def of panelOrder) {
    const panel = panels[def.key];
    clearPanelParticles(panel);

    if (def.key === 'ethanol') {
      const n = Math.max(3, Math.round(5 * c));
      for (let i = 0; i < n; i++) addNeutralMolecule(panel, i, basePositions[(i * 2 + 1) % basePositions.length]);
    } else if (def.key === 'kcl') {
      const pairs = Math.max(2, Math.round(4 * c));
      for (let i = 0; i < pairs; i++) addIon(panel, i, 'plus', basePositions[(i * 3 + 1) % basePositions.length]);
      for (let i = 0; i < pairs; i++) addIon(panel, i + pairs, 'minus', basePositions[(i * 3 + 6) % basePositions.length]);
    } else {
      const ionPairs = Math.max(1, Math.round(1.6 * c));
      const neutralN = Math.max(2, Math.round(3.5 * c));
      for (let i = 0; i < ionPairs; i++) addIon(panel, i, 'plus', basePositions[(i * 4 + 4) % basePositions.length]);
      for (let i = 0; i < ionPairs; i++) addIon(panel, i + ionPairs, 'minus', basePositions[(i * 5 + 8) % basePositions.length]);
      for (let i = 0; i < neutralN; i++) addNeutralMolecule(panel, i, basePositions[(i * 3 + 2) % basePositions.length]);
    }

    setBulbBrightness(panel, conductivityFor(def.key, c));
  }
}

