        const amp = state.particleMotion ? 0.024 : 0;
        rec.object.position.set(
          rec.base.x + amp * Math.sin(sec * 1.25 + rec.phase),
          rec.base.y + amp * 0.75 * Math.cos(sec * 1.45 + rec.phase),
          rec.base.z
        );
      } else {
        const amp = state.particleMotion ? 1 : 0;
        let x = rec.base.x;
        if (amp) {
          const localLeft = panel.def.x - 0.47;
          const span = 0.94;
          const raw = ((rec.base.x - localLeft + rec.speed * sec) % span + span) % span;
