function ellipsePoints(y, rx, rz, n = 96, zc = 0) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(Math.cos(a) * rx, y, zc + Math.sin(a) * rz));
  }
  return pts;
}

function tubeFromPoints(points, radius, mat, closed = false, segments = 72) {
  const curve = new THREE.CatmullRomCurve3(points, closed, 'catmullrom', 0.25);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, segments, radius, 8, closed), mat);
}

function bezierTube(p0, p1, p2, p3, radius, mat, segments = 72) {
  const curve = new THREE.CubicBezierCurve3(
    new THREE.Vector3(...p0),
    new THREE.Vector3(...p1),
    new THREE.Vector3(...p2),
    new THREE.Vector3(...p3)
  );
  return new THREE.Mesh(new THREE.TubeGeometry(curve, segments, radius, 10), mat);
}

function addPlateEdges(mesh, parent) {
