function disposeChildren(group) {
  group.traverse(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
  group.clear();
}

function clearPanelParticles(panel) {
