}

function addNeutralMolecule(panel, i, pos) {
  const mol = new THREE.Group();
  mol.position.set(pos[0], pos[1], pos[2]);
  const r = 0.058 + 0.004 * (i % 2);
  const offsets = i % 2
    ? [[-0.048, 0, 0], [0.048, 0.015, 0.004]]
    : [[-0.052, 0, 0], [0.052, 0.006, 0.004], [0, 0.058, 0.002]];
  offsets.forEach(o => {
    const s = new THREE.Mesh(new THREE.SphereGeometry(r, 24, 16), ionMat);
    s.position.set(o[0], o[1], o[2]);
    mol.add(s);
  });
  panel.particles.add(mol);
  panel.records.push({
    kind: 'neutral',
    object: mol,
    base: mol.position.clone(),
    phase: i * 0.83
  });
}

function addIon(panel, i, charge, pos) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.076, 28, 18), ionMat);
  mesh.position.set(pos[0], pos[1], pos[2]);
  panel.particles.add(mesh);

  const label = addLabel(charge === 'plus' ? '+' : '&minus;', worldPos(panel, mesh.position), {
    fontSize: '15px',
    bold: true,
    color: '#111',
    offset: [0, 0]
  });
  panel.dynamicLabels.push(label);

  const dir = charge === 'plus' ? new THREE.Vector3(-1, 0, 0) : new THREE.Vector3(1, 0, 0);
  const sideOffset = charge === 'plus' ? -0.13 : 0.11;
  const arrow = new THREE.ArrowHelper(
    dir,
    new THREE.Vector3(pos[0] + sideOffset, pos[1] - 0.02, pos[2] + 0.02),
    0.30,
    arrowColor,
    0.080,
    0.043
  );
  panel.arrows.add(arrow);

  panel.records.push({
    kind: charge,
    object: mesh,
    label,
    arrow,
    base: mesh.position.clone(),
    phase: i * 0.71,
    speed: charge === 'plus' ? -0.13 : 0.13,
    arrowOffset: sideOffset
  });
}

