  const coreRadius = on ? 0.13 + 0.20 * amount : 0.001;
  panel.glow.scale.set(radius, radius, radius);
  panel.glowCore.scale.set(coreRadius, coreRadius, coreRadius);
  panel.pointLight.intensity = 2.6 * amount;
  panel.filament.material.color.set(on ? (amount > 0.55 ? 0xff8a00 : 0xffc400) : 0x777777);
}

function rebuildAllParticles() {
  const c = state.concentration;
  for (const def of panelOrder) {
    const panel = panels[def.key];
    clearPanelParticles(panel);

    if (def.key === 'ethanol') {
      const n = Math.max(3, Math.round(5 * c));
      for (let i = 0; i < n; i++) addNeutralMolecule(panel, i, ethanolClusterPositions[i % ethanolClusterPositions.length]);
    } else if (def.key === 'kcl') {
      const pairs = Math.max(3, Math.round(4 * c));
      for (let i = 0; i < pairs; i++) addIon(panel, i, 'plus', kclIonPositions[(i * 2 + 1) % kclIonPositions.length]);
      for (let i = 0; i < pairs; i++) addIon(panel, i + pairs, 'minus', kclIonPositions[(i * 2 + 4) % kclIonPositions.length]);
    } else {
      const ionPairs = Math.max(1, Math.round(1.0 * c));
      const neutralN = Math.max(3, Math.round(3.2 * c));
      for (let i = 0; i < ionPairs; i++) addIon(panel, i, 'plus', aceticIonPositions[(i * 2) % aceticIonPositions.length]);
      for (let i = 0; i < ionPairs; i++) addIon(panel, i + ionPairs, 'minus', aceticIonPositions[(i * 2 + 1) % aceticIonPositions.length]);
      for (let i = 0; i < neutralN; i++) addNeutralMolecule(panel, i, aceticNeutralPositions[i % aceticNeutralPositions.length]);
    }

    setBulbBrightness(panel, conductivityFor(def.key, c));
  }
}

function syncUIAndFocus() {
  document.getElementById('concVal').textContent = state.concentration.toFixed(1);
  document.getElementById('soluteConcentration').value = state.concentration;
  document.querySelectorAll('#focusButtons button').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.focus === state.focus);
  });
  Object.values(panels).forEach(panel => {
    panel.focusFrame.visible = state.focus !== 'all' && state.focus === panel.def.key;
  });
  const motionBtn = document.getElementById('particleMotion');
  motionBtn.classList.toggle('active', state.particleMotion);
  motionBtn.textContent = state.particleMotion ? 'Pause particle motion' : 'Animate particle motion';
}

function updateMotion() {
  const sec = (performance.now() - motionStart) / 1000;
  for (const panel of Object.values(panels)) {
    for (const rec of panel.records) {
      if (rec.kind === 'neutral') {
        const amp = state.particleMotion ? 0.024 : 0;
        rec.object.position.set(
          rec.base.x + amp * Math.sin(sec * 1.25 + rec.phase),
          rec.base.y + amp * 0.75 * Math.cos(sec * 1.45 + rec.phase),
          rec.base.z
        );
      } else {
        const amp = state.particleMotion ? 1 : 0;
        let x = rec.base.x;
        if (amp) {
          const localLeft = -0.49;
          const span = 0.98;
          const raw = ((rec.base.x - localLeft + rec.speed * sec) % span + span) % span;
          x = localLeft + raw;
        }
        const y = rec.base.y + amp * 0.014 * Math.sin(sec * 2.4 + rec.phase);
        rec.object.position.set(x, y, rec.base.z);
        rec.label.pos.copy(worldPos(panel, rec.object.position));
        rec.arrow.position.set(x + rec.arrowOffset, y - 0.02, rec.base.z + 0.02);
      }
    }
  }
  requestAnimationFrame(updateMotion);
}

const explanations = {
  all: {
    title: 'Three solutions compared',
    body: 'The same circuit is dipped into three liquids. Ethanol has only neutral molecules and no light. KCl has many ions and a bright bulb. Acetic acid has mostly neutral molecules plus a few ions, so the bulb is dim.'
  },
  ethanol: {
    title: 'Ethanol: no conductivity',
    body: 'The green clusters are neutral ethanol molecules. Because there are no mobile charged ions inside the beaker, charge cannot cross the liquid and the bulb remains dark.'
  },
  kcl: {
    title: 'KCl: high conductivity',
    body: 'KCl is shown as fully dissociated ions. Positive ions drift toward the negative plate, while negative ions drift toward the positive plate, completing the circuit and lighting the bulb strongly.'
  },
  acetic: {
    title: 'Acetic acid solution: low conductivity',
    body: 'Most acetic acid particles remain neutral molecules. Only a few ions are present, so the solution conducts weakly and the bulb glows dimly.'
  }
};

document.querySelectorAll('#focusButtons button').forEach(btn => {
  btn.addEventListener('click', () => {
    state.focus = btn.dataset.focus;
    syncUIAndFocus();
    document.getElementById('stepText').innerHTML = '';
    const ex = explanations[state.focus];
    showPopup(ex.title, ex.body);
  });
});

document.getElementById('soluteConcentration').addEventListener('input', e => {
  state.concentration = Math.min(1.5, Math.max(0.4, Number(e.target.value)));
  rebuildAllParticles();
  syncUIAndFocus();
  document.getElementById('stepText').innerHTML = 'Changing the amount changes the number of solute particles shown. KCl remains much brighter than weakly ionized acetic acid.';
});

document.getElementById('particleMotion').addEventListener('click', () => {
  state.particleMotion = !state.particleMotion;
  syncUIAndFocus();
});

const demoSteps = [
  {
    focus: 'ethanol',
    title: 'Ethanol: no conductivity',
    narration: 'Only neutral molecule clusters are present in the liquid. With no mobile charge carriers between the plates, the bulb is off.'
  },
  {
    focus: 'kcl',
    title: 'KCl: high conductivity',
    narration: 'KCl separates into many positive and negative ions. The arrows show ions moving toward oppositely charged electrodes, so the bulb glows brightly.'
  },
  {
    focus: 'acetic',
    title: 'Acetic acid: low conductivity',
    narration: 'Most particles remain neutral molecules. A few ions are present, so the solution conducts weakly and the bulb is dim.'
  }
];

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  state.focus = step.focus;
  syncUIAndFocus();
  document.getElementById('stepText').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  showPopup(step.title, step.narration);
}

document.querySelectorAll('[data-step]').forEach(btn => {
  btn.addEventListener('click', () => goToStep(Number(btn.dataset.step)));
});

rebuildAllParticles();
syncUIAndFocus();
updateMotion();
